<?php
declare(strict_types=1);
use DigiForgePrintifyConnector\Preparation\{CoreContractAdapter,ReviewCoordinator,OperationsCoreInterface,ShipmentReadModel,ReviewPanel};
use DigiForge\Connector\Printify\ShopBinding;
final class PrintifyCompanionBatch5IntegrationTest extends WP_UnitTestCase {
 public function set_up():void{parent::set_up();require_once dirname(__DIR__,2).'/companion/digiforge-printify-connector/digiforge-printify-connector.php';}
 public function testNativeAdministratorHasNoImplicitCompanionReviewAuthority():void{[$s]=(require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();$actor=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($actor);$before=rest_get_server()->get_routes();$cron=_get_cron_array();self::assertWPError(DigiForgePrintifyConnector\Plugin::reviews()->queue($s,$actor));self::assertWPError(CoreContractAdapter::localScope('personalized_pod',$actor));self::assertFalse(CoreContractAdapter::inspect()['execution_authorized']);self::assertSame($before,rest_get_server()->get_routes());self::assertSame($cron,_get_cron_array());self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));}
 public function testSyntheticCoreReviewAndFulfillmentStayBoundToCurrentActor():void {
  require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$s,$o,$ship,$alloc,$ctx]=(require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();$actor=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($actor);
  $p=new class($actor) implements OperationsCoreInterface {
   public SyntheticOperationsCore $core;public function __construct(private int $actor){$this->core=new SyntheticOperationsCore();}public function version():string{return '1.0.0';}public function workflowVersion():string{return '1.0.0';}public function operationsVersion():string{return '1.0.0';}public function exchange(array $q):array|WP_Error{return new WP_Error('no_dispatch');}
   public function authorizeWorkflow(ShopBinding $s,int $a,string $action):array|WP_Error{if(get_current_user_id()!==$this->actor||$a!==$this->actor||!current_user_can('manage_options'))return new WP_Error('synthetic_actor_denied');return $this->core->authorizeWorkflow($s,$a,$action);}public function withWebhookSecret(ShopBinding $s,callable $v):mixed{return new WP_Error('not_used');}public function recordWorkflow(array $q):array|WP_Error{return new WP_Error('not_used');}public function inspectWorkflows(ShopBinding $s,int $a,int $l):array|WP_Error{return new WP_Error('not_used');}
   public function reviewQueue(ShopBinding $s,int $a,int $l):array|WP_Error{return $this->core->reviewQueue($s,$a,$l);}public function decideReview(array $q):array|WP_Error{return $this->core->decideReview($q);}public function recordFulfillment(array $q):array|WP_Error{return $this->core->recordFulfillment($q);}public function inspectFulfillment(ShopBinding $s,int $a,string $id):ShipmentReadModel|WP_Error{return $this->core->inspectFulfillment($s,$a,$id);}
  };
  $w=new ReviewCoordinator($p);$q=$w->queue($s,$actor);self::assertIsArray($q);$r=$w->decide($s,$actor,$q['items'][0],'ACKNOWLEDGE','UNCERTAINTY_RETAINED');self::assertSame('ACKNOWLEDGED',$r['review_state']);self::assertFalse($r['external_execution_authorized']);self::assertStringContainsString('local only',ReviewPanel::render($w,$s,$actor));$m=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);$p->core->inspectionModel=$m;self::assertSame('RECORDED',$w->observeFulfillment($s,$actor,$m)['disposition']);wp_set_current_user(0);self::assertWPError($w->queue($s,$actor));self::assertWPError($w->observeFulfillment($s,$actor,$m));
 }
}
